{"source":"import json
import sys
from datetime import datetime, timezone

def parse_offset_aware(s):
    """Parse an offset-aware ISO8601 string into a datetime."""
    return datetime.fromisoformat(s)

def is_naive_or_invalid(due):
    """Return True if due is None, missing, or naive (no timezone)."""
    if due is None:
        return True
    try:
        dt = datetime.fromisoformat(due)
        # Check if timezone aware
        if dt.tzinfo is None:
            return True
        return False
    except (ValueError, TypeError):
        return True

def main():
    with open(sys.argv[1]) as f:
        data = json.load(f)

    as_of = parse_offset_aware(data["as_of"])

    results = []
    for r in data["reminders"]:
        # Skip completed reminders
        if r.get("completed", False):
            continue

        due_str = r.get("due")

        # Skip null, missing, or naive due values
        if is_naive_or_invalid(due_str):
            continue

        due_dt = parse_offset_aware(due_str)

        # Compare actual instants, include if due <= as_of
        if due_dt <= as_of:
            # Format due_utc as YYYY-MM-DDTHH:MM:SSZ
            due_utc = due_dt.astimezone(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
            results.append({
                "id": r["id"],
                "title": r["title"],
                "due_utc": due_utc,
                "_due_instant": due_dt.timestamp()
            })

    # Sort by actual due instant then id
    results.sort(key=lambda x: (x["_due_instant"], x["id"]))

    # Remove internal sorting key
    output = [{"id": r["id"], "title": r["title"], "due_utc": r["due_utc"]} for r in results]
    print(json.dumps(output))

if __name__ == "__main__":
    main()
